using ROM.UI.Sprint01;using System;using System.Collections.Generic;using System.Linq;using Mirror;using MultiFPS;using MultiFPS.Gameplay;using MultiFPS.Gameplay.RiftCombat;using MultiFPS.UI;using UnityEngine;using UnityEngine.SceneManagement;
namespace ROM.Progression {
// Stationary networked drops; only the server can consume them or grant stored loot.
public sealed class RiftGroundLoot:NetworkBehaviour {
 public const uint Asset=0x524c5431;
 [SyncVar]public string OwnerCharacter,ItemId;
 [SyncVar]public string DefinitionId="nertor-axe",RarityName="Común";[SyncVar]public Rarity RarityKind;[SyncVar]public Color RarityColor;[SyncVar]public float LevelMultiplier=1,RarityMultiplier=1;
 [SyncVar]public bool Axe,Claimed;
 [SyncVar]public int Gold,ItemLevel;
 [SyncVar]public float WeaponMultiplier=1;
 [SyncVar]public double Expires;
 static readonly HashSet<string> deaths=new HashSet<string>();
 public static readonly List<RiftGroundLoot> Active=new List<RiftGroundLoot>();
 readonly List<Material> axeMaterials=new List<Material>();RiftWorldTarget target;Transform art;Material coinMaterial,traceMaterial;LineRenderer pickupTrace;float nextAuto,retryAt;bool visualBuilt;
 public static void Register(){NetworkClient.RegisterSpawnHandler(Asset,(SpawnMessage m)=>Create(m.position),go=>UnityEngine.Object.Destroy(go));}
 public static void ResetReceipts()=>deaths.Clear();
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Install(){deaths.Clear();Active.Clear();Register();SceneManager.sceneLoaded-=SceneLoaded;SceneManager.sceneLoaded+=SceneLoaded;if(!UnityEngine.Object.FindFirstObjectByType<RiftLootLifecycle>())new GameObject("Rift loot lifecycle").AddComponent<RiftLootLifecycle>();}
 static void SceneLoaded(Scene scene,LoadSceneMode mode){Register();}
 static GameObject Create(Vector3 position){var go=new GameObject("Rift ground loot");go.SetActive(false);var id=go.AddComponent<NetworkIdentity>();id.sceneId=0;go.AddComponent<RiftGroundLoot>();var box=go.AddComponent<BoxCollider>();box.center=Vector3.up*.3f;box.size=new Vector3(.8f,.6f,.8f);box.isTrigger=true;go.transform.position=position;go.SetActive(true);return go;}
 public static void ServerDropForKill(PlayerInstance player,uint victim,Vector3 position,int gold,RiftLootTableDefinition overrideTable=null){if(!NetworkServer.active||!player||player.BOT||victim==0||string.IsNullOrEmpty(player.PlayerInfo.CharacterId))return;string token=player.gameObject.scene.handle+":"+victim;if(!deaths.Add(token))return;var tuning=RiftLootTuning.Load;if(!tuning)return;var combat=player.GetComponent<AbilityController>();if(gold>0)ServerCreate(player,position+Vector3.right*.35f,gold,0);var table=overrideTable?overrideTable:tuning.DefaultTable;if(combat&&combat.Prototype&&table&&table.TryRoll(combat.Level,combat.Progression.MaximumLevel,()=>UnityEngine.Random.value,out var roll,item=>tuning.Catalog!=null&&tuning.Catalog.Contains(item)))ServerCreate(player,position-Vector3.right*.35f,0,roll.Level,roll);}
 public static RiftGroundLoot ServerCreate(PlayerInstance player,Vector3 point,int gold,int level,RiftLootRoll roll=null){if(!NetworkServer.active||!player||string.IsNullOrEmpty(player.PlayerInfo.CharacterId)||!RiftLootTuning.Load||(gold<=0&&level<=0))return null;if(Physics.Raycast(point+Vector3.up*3,Vector3.down,out var hit,8,GameManager.environmentLayer,QueryTriggerInteraction.Ignore))point=hit.point+Vector3.up*.08f;var drop=Create(point).GetComponent<RiftGroundLoot>();drop.OwnerCharacter=player.PlayerInfo.CharacterId;drop.ItemId=Guid.NewGuid().ToString("N");drop.Axe=level>0;drop.Gold=Mathf.Max(0,gold);var ownerCombat=player.GetComponent<AbilityController>();drop.ItemLevel=Mathf.Clamp(level,1,ownerCombat?ownerCombat.Progression.MaximumLevel:1);drop.LevelMultiplier=RiftLootTuning.Load.Multiplier(drop.ItemLevel);drop.WeaponMultiplier=drop.LevelMultiplier;drop.RarityColor=new Color(.82f,.84f,.88f);if(roll!=null&&drop.Axe){drop.DefinitionId=roll.Item.Id;drop.RarityKind=roll.Rarity;drop.RarityName=roll.RarityName;drop.RarityColor=roll.Tint;drop.RarityMultiplier=roll.RarityMultiplier;drop.LevelMultiplier=roll.LevelMultiplier;drop.WeaponMultiplier=roll.PowerMultiplier;}drop.Expires=NetworkTime.time+RiftLootTuning.Load.Lifetime;NetworkServer.Spawn(drop.gameObject,Asset);return drop;}
 void OnEnable(){Active.Add(this);}void OnDisable(){Active.Remove(this);}
 public override void OnStartClient(){target=gameObject.AddComponent<RiftWorldTarget>();target.InteractionRange=RiftLootTuning.Load.ClickRange;target.InteractRequested+=Click;BuildVisual();}
 public void RequestPickup()=>Click();
 void Click(){var player=ClientFrontend.ClientPlayerInstance;if(player)player.GetComponent<RiftJournalPlayer>()?.CmdTakeLoot(netId);}
 public bool ServerTake(RiftJournalPlayer journal,bool automatic){if(!isServer||Claimed||!journal||NetworkTime.time>=Expires)return false;var player=journal.GetComponent<PlayerInstance>();var actor=player?player.MyCharacter:null;var tuning=RiftLootTuning.Load;if(!actor||actor.Health.CurrentHealth<=0||actor.gameObject.scene!=gameObject.scene||player.PlayerInfo.CharacterId!=OwnerCharacter||!tuning)return false;float range=automatic?tuning.AutoPickupRadius:tuning.ClickRange;if(Vector3.Distance(actor.transform.position,transform.position)>range)return false;Vector3 start=actor.transform.position+Vector3.up*1.2f,delta=transform.position+Vector3.up*.3f-start;if(gameObject.scene.GetPhysicsScene().Raycast(start,delta.normalized,out _,delta.magnitude,GameManager.environmentLayer,QueryTriggerInteraction.Ignore))return false;Claimed=true;if(!journal.ServerAcceptLoot(this)){Claimed=false;return false;}NetworkServer.Destroy(gameObject);return true;}
 void Update(){if(isServer&&NetworkTime.time>=Expires){NetworkServer.Destroy(gameObject);return;}if(isServer&&!Claimed&&Time.time>=nextAuto){nextAuto=Time.time+.2f;foreach(var p in GameManager.Players)if(p&&!p.BOT&&p.MyCharacter&&p.PlayerInfo.CharacterId==OwnerCharacter){var journal=p.GetComponent<RiftJournalPlayer>();if(journal&&Time.time>=retryAt&&Vector3.Distance(p.MyCharacter.transform.position,transform.position)<=RiftLootTuning.Load.AutoPickupRadius){if(!ServerTake(journal,true))retryAt=Time.time+2;}break;}}
  if(isClient&&!visualBuilt)BuildVisual();if(art){var local=ClientFrontend.ClientPlayerInstance;bool mine=local&&local.PlayerInfo.CharacterId==OwnerCharacter;art.gameObject.SetActive(mine&&!Claimed);if(pickupTrace)pickupTrace.gameObject.SetActive(mine&&!Claimed&&local.MyCharacter&&Vector3.Distance(local.MyCharacter.transform.position,transform.position)<10);if(target){target.enabled=mine&&!Claimed;var hitbox=GetComponent<Collider>();if(hitbox)hitbox.enabled=mine&&!Claimed;target.Id="loot:"+netId;target.DisplayName=Axe?RarityName+" · Hacha de Nertör · nivel "+ItemLevel:Gold+" oro de El Rift";target.Role="Botín · clic cerca o pasá por encima";}}}
 void BuildVisual(){if(visualBuilt)return;var local=ClientFrontend.ClientPlayerInstance;var c=local?local.GetComponent<AbilityController>():null;if(!c||!c.Specialization)return;art=new GameObject("Loot visual only").transform;art.SetParent(transform,false);if(Axe){var item=RiftLootTuning.Load.Item(DefinitionId);var weapon=item?item.Weapon:c.Specialization.Weapon;var source=weapon?weapon.Model:null;if(!source){Destroy(art.gameObject);art=null;return;}foreach(var filter in source.GetComponentsInChildren<MeshFilter>(true)){var renderer=filter.GetComponent<MeshRenderer>();if(!filter.sharedMesh||!renderer)continue;var part=new GameObject(filter.name).transform;part.SetParent(art,false);part.localPosition=source.transform.InverseTransformPoint(filter.transform.position);part.localRotation=Quaternion.Inverse(source.transform.rotation)*filter.transform.rotation;part.localScale=filter.transform.lossyScale;part.gameObject.AddComponent<MeshFilter>().sharedMesh=filter.sharedMesh;part.gameObject.AddComponent<MeshRenderer>().sharedMaterials=renderer.sharedMaterials.Select(sourceMaterial=>{if(!sourceMaterial)return sourceMaterial;var copy=new Material(sourceMaterial);if(copy.HasProperty("_EmissionColor")){copy.EnableKeyword("_EMISSION");copy.SetColor("_EmissionColor",copy.GetColor("_EmissionColor")+new Color(RarityColor.r*.3f,RarityColor.g*.3f,RarityColor.b*.3f));}axeMaterials.Add(copy);return copy;}).ToArray();}var renderers=art.GetComponentsInChildren<Renderer>();if(renderers.Length>0){var bounds=renderers[0].bounds;foreach(var x in renderers)bounds.Encapsulate(x.bounds);float scale=.9f/Mathf.Max(.01f,bounds.size.magnitude);art.localScale=Vector3.one*scale;art.localRotation=Quaternion.Euler(80,25,0);art.localPosition=Vector3.zero;bounds=renderers[0].bounds;foreach(var x in renderers)bounds.Encapsulate(x.bounds);art.position+=new Vector3(transform.position.x-bounds.center.x,transform.position.y+.03f-bounds.min.y,transform.position.z-bounds.center.z);}}else{var shader=Shader.Find("Universal Render Pipeline/Lit");coinMaterial=new Material(shader);coinMaterial.color=new Color(.85f,.57f,.12f);coinMaterial.EnableKeyword("_EMISSION");coinMaterial.SetColor("_EmissionColor",new Color(.65f,.38f,.07f));for(int i=0;i<Mathf.Clamp(Gold,1,6);i++){var coin=GameObject.CreatePrimitive(PrimitiveType.Cylinder);UnityEngine.Object.Destroy(coin.GetComponent<Collider>());coin.transform.SetParent(art,false);coin.transform.localPosition=new Vector3((i%3-1)*.12f,.025f+(i/3)*.035f,(i%2)*.08f);coin.transform.localScale=new Vector3(.18f,.018f,.18f);coin.GetComponent<Renderer>().sharedMaterial=coinMaterial;}}var trace=new GameObject("Subtle physical pickup trace");trace.transform.SetParent(transform,false);pickupTrace=trace.AddComponent<LineRenderer>();pickupTrace.useWorldSpace=false;pickupTrace.loop=true;pickupTrace.widthMultiplier=.11f;pickupTrace.positionCount=32;traceMaterial=new Material(Shader.Find("Universal Render Pipeline/Unlit"));ConfigureGlow(traceMaterial,Axe?RarityColor:new Color(1,.72f,.22f));pickupTrace.sharedMaterial=traceMaterial;for(int n=0;n<32;n++){float angle=n*Mathf.PI*2/32;pickupTrace.SetPosition(n,new Vector3(Mathf.Cos(angle)*.22f,.025f,Mathf.Sin(angle)*.22f));}visualBuilt=true;}
 static Texture2D glowTexture;
 static void ConfigureGlow(Material material,Color tint){if(!glowTexture){glowTexture=new Texture2D(1,32,TextureFormat.RGBA32,false);glowTexture.name="Shared feathered loot glow";glowTexture.wrapMode=TextureWrapMode.Clamp;glowTexture.filterMode=FilterMode.Bilinear;glowTexture.hideFlags=HideFlags.HideAndDontSave;for(int y=0;y<32;y++){float a=Mathf.Sin(Mathf.PI*y/31);glowTexture.SetPixel(0,y,new Color(1,1,1,a*a));}glowTexture.Apply(false,true);}material.SetFloat("_Surface",1);material.SetFloat("_Blend",2);material.SetInt("_SrcBlend",(int)UnityEngine.Rendering.BlendMode.SrcAlpha);material.SetInt("_DstBlend",(int)UnityEngine.Rendering.BlendMode.One);material.SetInt("_ZWrite",0);material.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");material.renderQueue=3000;tint.a=.48f;material.SetColor("_BaseColor",tint);material.SetTexture("_BaseMap",glowTexture);}
 void OnDestroy(){if(target)target.InteractRequested-=Click;if(coinMaterial)Destroy(coinMaterial);if(traceMaterial)Destroy(traceMaterial);foreach(var copy in axeMaterials)if(copy)Destroy(copy);}
}
public sealed class RiftLootLifecycle:MonoBehaviour {bool serving,connected;void Awake(){DontDestroyOnLoad(gameObject);if(!GetComponent<RiftLootLabels>())gameObject.AddComponent<RiftLootLabels>();NetworkClient.OnConnectedEvent+=Connected;}void Connected(){RiftGroundLoot.Register();connected=true;}void Update(){if(!NetworkClient.active){connected=false;NetworkClient.OnConnectedEvent-=Connected;NetworkClient.OnConnectedEvent+=Connected;}else if(!connected)Connected();if(serving&&!NetworkServer.active)RiftGroundLoot.ResetReceipts();serving=NetworkServer.active;}void OnDestroy(){NetworkClient.OnConnectedEvent-=Connected;}}
}
